example_item.example_item_data:
% Label a simulated fibrillation night and read its atrial fibrillation burden.
recording = ecglab.simulate('Seconds', 90, 'Fibrillation', true, 'Seed', 7);
rhythm = ecglab.rhythm(recording);
fprintf('AF burden %.2f\n', rhythm.afBurden);

% Detect the rhythm of an AF Database record and score it against its marks.
recording = ecglab.reference('afdb/04015');
detected = ecglab.rhythm(recording);
agreement = ecglab.validate(detected, recording, 'Kind', 'episodes');
fprintf('duration Se %.2f  +P %.2f\n', agreement.durationSe, agreement.durationPpv);
